function crimeRecord(city){
 const c=CITIES[city];
 if(!c)return null;
 if(CRIME_ADDITIONAL[city])return CRIME_ADDITIONAL[city];
 if(CRIME_VERIFIED[city])return {...CRIME_VERIFIED[city],rating:"Оценка не определена: отсутствует сопоставимая городская ставка на 100 000 жителей."};
 if(c.country==="Финляндия")return {text:"2025 · Финляндия: 553 536 зарегистрированных преступлений по Уголовному кодексу, в том числе 267 276 имущественных. Это показатель страны, а не города.",url:"https://pxdata.stat.fi/PxWeb/pxweb/en/StatFin/StatFin__rpk/statfin_rpk_pxt_13m3.px/",name:"Statistics Finland — Recorded Offences",rating:"Оценка города не определена: приведена статистика страны."};
 return null;
}
function crimeInfo(city){
 const r=crimeRecord(city);
 return r?`${r.text} ${r.rating}`:"Числовой показатель для этого города пока не подтверждён. Оценка (низкий / средний / высокий) не присвоена, чтобы не вводить в заблуждение.";
}
function cityHTML(u){
 const key=CITY_BY_UNI[u.n],c=CITIES[key];if(!c)return `<p class="hint">Городская карточка готовится.</p>`;
 const facts=[['Стоимость жизни',c.cost],['Транспорт',c.transport],['Климат',c.climate],['Экология и природа',c.environment],['Повседневная жизнь',c.life],['Безопасность',c.safety]];
 return `<div class="city-intro"><span class="city-place">${esc(key)}, ${esc(c.country)}</span><p>Сведения для сравнения городов. Условия жизни и безопасность могут различаться по районам.</p></div><div class="city-facts">${facts.map(([h,t])=>`<section class="city-fact"><h3>${h}</h3><p>${esc(t)}</p></section>`).join('')}</div><div class="city-sources"><b>Источники</b>${c.sources.map(([n,url])=>`<a href="${esc(url)}" target="_blank" rel="noopener noreferrer">${esc(n)} ↗</a>`).join('')}</div>`;
}
function openCity(i){const u=U[i],key=CITY_BY_UNI[u.n];if(!key)return;$('#cityTitle').textContent=`${key} — информация о городе`;$('#cityBody').innerHTML=cityHTML(u);$('#cityDialog').showModal();}
document.querySelector('#cityClose').addEventListener('click',()=>document.querySelector('#cityDialog').close());
document.querySelector('#cityDialog').addEventListener('click',e=>{if(e.target===document.querySelector('#cityDialog'))document.querySelector('#cityDialog').close()});
U.forEach((u,i)=>{u.i=i});
const byName=new Map(U.map(u=>[u.n,u]));
const COUNTRIES=[...new Set(U.map(u=>u.c))].sort((a,b)=>a.localeCompare(b,"ru"));
const CAT={reach:{n:"Reach",s:"амбициозный"},match:{n:"Match",s:"подходящий"},safety:{n:"Safety",s:"реалистичный"}};

/* ---------- Состояние и localStorage ---------- */
const DEF=()=>({a:{level:"",countries:[],all:false,field:"",scale:"4",gpa:"",sat:"",ielts:"",ent:"",bval:"",bcur:"KZT"},rate:500,saved:[],cmp:[],done:false,plan:{done:{},dl:{}},calc:{cur:"USD",v:[18000,9000,0,0,0,0],g:50,y:4}});
function load(){
  const s=DEF();let r=null;
  try{r=JSON.parse(localStorage.getItem(LS_KEY)||"null")}catch(e){}
  if(!r||typeof r!=="object")return s;
  const a=r.a&&typeof r.a==="object"?r.a:{};
  const ns=(v,lo,hi)=>{if(v===""||v==null)return"";const n=Number(v);return isFinite(n)&&n>=lo&&n<=hi?String(v):""};
  if(a.level==="Бакалавриат"||a.level==="Магистратура")s.a.level=a.level;
  if(Array.isArray(a.countries))s.a.countries=[...new Set(a.countries.filter(c=>COUNTRIES.includes(c)))];
  s.a.all=a.all===true&&s.a.countries.length===0;
  if(a.field==="any"||Object.prototype.hasOwnProperty.call(F,a.field))s.a.field=a.field;
  if(a.scale==="5")s.a.scale="5";
  s.a.gpa=ns(a.gpa,0,s.a.scale==="5"?5:4);
  s.a.sat=ns(a.sat,400,1600);s.a.ielts=ns(a.ielts,0,9);s.a.ent=ns(a.ent,0,140);s.a.bval=ns(a.bval,0,1e10);
  if(a.bcur==="USD")s.a.bcur="USD";
  if(Number(r.rate)>0&&Number(r.rate)<1e5)s.rate=Number(r.rate);
  if(Array.isArray(r.saved))s.saved=[...new Set(r.saved.filter(n=>byName.has(n)))];
  if(Array.isArray(r.cmp))s.cmp=[...new Set(r.cmp.filter(n=>byName.has(n)))].slice(0,MAX_CMP);
  s.done=r.done===true;
  if(r.plan&&typeof r.plan==="object"){
    for(const k in (r.plan.done||{}))if(/^[a-z0-9_]{1,30}$/.test(k)&&r.plan.done[k]===true)s.plan.done[k]=true;
    for(const k in (r.plan.dl||{}))if(/^[a-z0-9_]{1,30}$/.test(k)&&/^\d{4}-\d{2}-\d{2}$/.test(r.plan.dl[k]))s.plan.dl[k]=r.plan.dl[k];
  }
  if(r.calc&&typeof r.calc==="object"){
    const c=r.calc;
    if(c.cur==="KZT")s.calc.cur="KZT";
    if(Array.isArray(c.v)&&c.v.length===6&&c.v.every(x=>isFinite(Number(x))&&Number(x)>=0))s.calc.v=c.v.map(Number);
    if(isFinite(Number(c.g))&&c.g>=0&&c.g<=100)s.calc.g=Number(c.g);
    if(Number.isInteger(Number(c.y))&&c.y>=1&&c.y<=8)s.calc.y=Number(c.y);
  }
  return s;
}
let S=load();
function save(){try{localStorage.setItem(LS_KEY,JSON.stringify(S))}catch(e){}}

/* ---------- Форматирование и безопасность ---------- */
const esc=s=>String(s==null?"":s).replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]));
const nf=new Intl.NumberFormat("ru-RU",{maximumFractionDigits:0});
const usd=n=>nf.format(Math.round(n))+" $";
const kzt=n=>nf.format(Math.round(n*S.rate))+" ₸";

/* ---------- Профиль и оценка ---------- */
function budgetUSD(){const v=+S.a.bval;if(!isFinite(v))return 0;return S.a.bcur==="KZT"?v/S.rate:v}
function prof(){
  const a=S.a,gpa=a.gpa===""?null:+a.gpa;
  return{level:a.level,field:a.field,g4:gpa===null?null:(a.scale==="5"?gpa*0.8:gpa),sat:a.sat===""?null:+a.sat,ielts:a.ielts===""?null:+a.ielts,ent:a.ent===""?null:+a.ent,budget:budgetUSD()};
}
const countryOk=u=>S.a.all||S.a.countries.includes(u.c);
const isComplete=()=>!!(S.a.level&&S.a.field&&S.a.gpa!==""&&S.a.bval!=="");

function evaluate(u,P){
  const bach=P.level==="Бакалавриат";
  const total0=u.t+u.l,costG=u.t*(1-u.gr/100)+u.l;
  const met=[],unmet=[],tips=[],notes=[],m=[];let missing=0,idx=100;
  if(P.field&&P.field!=="any"&&F[P.field])met.push(`Направление «${F[P.field]}» есть в университете`);
  const d=P.g4-u.g;
  if(d>=0)met.push(`GPA ≈ ${P.g4.toFixed(2)} (шкала 4.0) — не ниже ориентира ${u.g.toFixed(1)}`);
  else{unmet.push(`GPA ≈ ${P.g4.toFixed(2)} ниже ориентира ${u.g.toFixed(1)}`);tips.push(`Подтянуть успеваемость: до ориентира не хватает ≈ ${(-d).toFixed(2)} по шкале 4.0`);idx-=Math.min(40,-d*50)}
  m.push(d/0.4);
  if(u.e>0){
    if(P.ielts===null){unmet.push(`IELTS не сдан — ориентир от ${u.e.toFixed(1)}`);tips.push(`Сдать IELTS (ориентир от ${u.e.toFixed(1)})`);missing++;idx-=6}
    else if(P.ielts>=u.e){met.push(`IELTS ${P.ielts} — не ниже ${u.e.toFixed(1)}`);m.push(P.ielts-u.e)}
    else{unmet.push(`IELTS ${P.ielts} ниже ориентира ${u.e.toFixed(1)}`);tips.push(`Повысить IELTS минимум на ${(u.e-P.ielts).toFixed(1)}`);idx-=Math.min(30,(u.e-P.ielts)*20);m.push(P.ielts-u.e)}
  }else met.push("IELTS не требуется (проверьте язык обучения)");
  if(bach){
    if(u.s>0){
      if(P.sat===null){unmet.push(`SAT не сдан — ориентир от ${u.s}`);tips.push(`Сдать SAT (ориентир от ${u.s})`);missing++;idx-=6}
      else if(P.sat>=u.s){met.push(`SAT ${P.sat} — не ниже ${u.s}`);m.push((P.sat-u.s)/150)}
      else{unmet.push(`SAT ${P.sat} ниже ориентира ${u.s}`);tips.push(`Повысить SAT минимум на ${u.s-P.sat} баллов`);idx-=Math.min(25,(u.s-P.sat)/10);m.push((P.sat-u.s)/150)}
    }else met.push("SAT не требуется");
  }
  let bs;
  if(total0<=P.budget){bs="ok";met.push(`Стоимость без гранта (${usd(total0)} в год) укладывается в бюджет`)}
  else if(costG<=P.budget){bs="grant";unmet.push(`Без гранта ${usd(total0)} в год — выше бюджета; в рамки вы попадаете только при условном гранте`);tips.push(`Искать гранты: без них не хватает ${usd(total0-P.budget)} в год`);idx-=6}
  else{bs="over";unmet.push(`Даже при условном гранте ${usd(costG)} в год — выше бюджета`);tips.push(`Не хватает ≈ ${usd(costG-P.budget)} в год даже с грантом-ориентиром`);idx-=Math.min(35,(costG-P.budget)/Math.max(u.t,2000)*40+8)}
  if(u.c==="Казахстан")notes.push("Поступление в казахстанские вузы и на ГОСО обычно идёт через ЕНТ; проходные баллы меняются по группе программ и году конкурса; проверьте ежегодную таблицу МНВО РК."+(P.ent!==null?` Ваш балл ЕНТ: ${P.ent}.`:""));
  const a=m.reduce((x,y)=>x+y,0)/m.length,w=Math.min(...m),sel=u.g>=3.7||u.s>=1500;
  let cat;
  if(!sel&&w>=0.25&&a>=0.5&&!missing)cat="safety";
  else if(w>=-0.3&&(!sel||a>=0.3))cat="match";
  else cat="reach";
  if(sel)notes.push("Очень конкурентный отбор: одних минимальных требований недостаточно.");
  const why=cat==="safety"?"Более реалистичный вариант: ваши показатели выше ориентировочных минимумов."
    :cat==="match"?"Подходящий вариант: ваш профиль близок к ориентировочным требованиям."
    :"Амбициозный вариант: часть требований пока не выполнена или отбор очень конкурентный.";
  return{u,cat,idx:Math.max(5,Math.round(idx)),total0,costG,bs,met,unmet,tips,notes,why,missing};
}
function results(){
  const P=prof();if(P.g4===null)return[];
  return U.filter(u=>countryOk(u)&&(P.field==="any"||u.f.includes(P.field))).map(u=>evaluate(u,P));
}
function grantsFor(u){return fundingFor(u)}

/*=== UI ===*/
const $=(s,r=document)=>r.querySelector(s),$$=(s,r=document)=>[...r.querySelectorAll(s)];
function toast(m){const t=$("#toast");t.textContent=m;t.classList.add("on");clearTimeout(toast.h);toast.h=setTimeout(()=>t.classList.remove("on"),2400)}
const reduce=()=>window.matchMedia&&matchMedia("(prefers-reduced-motion: reduce)").matches;
const val=x=>x===TBD?`<span class="tbd">${TBD}</span>`:esc(x);
const normStr=s=>String(s).toLowerCase().replace(/ё/g,"е").trim();

/* ---------- Карточка университета ---------- */
function grantHTML(gr,u){
  const url=gr.url==="@"?u.w:(gr.url||u.w);
  const link=url?`<a href="${esc(url)}" target="_blank" rel="noopener noreferrer">${gr.url==="@"?"Сайт университета (раздел стипендий)":"Официальный сайт программы"} ↗</a>`:`<span class="tbd">${TBD}</span>`;
  return `<div class="grant"><h5>${esc(gr.n)}</h5><dl>
  <dt>Размер</dt><dd>${val(gr.amt)}</dd><dt>Покрывает</dt><dd>${val(gr.cov)}</dd>
  <dt>Требования</dt><dd>${val(gr.req)}</dd><dt>IELTS / SAT</dt><dd>${val(gr.tst)}</dd>
  <dt>Для кого</dt><dd>${val(gr.who)}</dd><dt>Уровень</dt><dd>${val(gr.lvl)}</dd>
  <dt>Дедлайн</dt><dd>${val(gr.dl)}</dd><dt>Ссылка</dt><dd>${link}</dd></dl></div>`;
}
function evHTML(ev){
  const li=a=>a.map(x=>`<li>${esc(x)}</li>`).join("");
  return `<p class="why">${esc(ev.why)}</p>
  <div class="cols"><div><h4>✓ Выполнено</h4><ul>${li(ev.met)||"<li>—</li>"}</ul></div><div><h4>✗ Ещё не выполнено</h4><ul>${li(ev.unmet)||"<li>Все ориентиры выполнены</li>"}</ul></div></div>
  ${ev.tips.length?`<div class="tips"><h4>Что улучшить</h4><ul>${li(ev.tips)}</ul></div>`:""}
  ${ev.notes.length?`<div class="notes"><ul class="bul">${li(ev.notes)}</ul></div>`:""}`;
}
function uniCard(u,ev){
  const sv=S.saved.includes(u.n),cm=S.cmp.includes(u.n);
  const total0=u.t+u.l,costG=u.t*(1-u.gr/100)+u.l,gl=fundingFor(u),fld=S.a.field,city=CITY_BY_UNI[u.n];
  return `<article class="card uni">
  <header class="uh"><div><h3>${esc(u.n)}</h3><span class="sub">${esc(u.c)}</span></div>${ev?`<span class="badge ${ev.cat}" title="Индекс соответствия профиля — не вероятность поступления">${CAT[ev.cat].n}<small>${CAT[ev.cat].s} · индекс ${ev.idx}</small></span>`:""}</header>
  ${ev?evHTML(ev):""}
  <p class="desc">${esc(u.d)}</p>
  <button type="button" class="city-trigger" data-act="city" data-i="${u.i}">Информация о городе <span>↗</span></button>
  <div class="chips">${[...u.f].map(k=>`<span class="chip${fld===k?" on":""}">${esc(F[k])}</span>`).join("")}</div>
  <div class="costs">
    <div><span>Обучение в год</span><b>${usd(u.t)}</b></div>
    <div><span>Проживание и расходы в год (оценка)</span><b>${usd(u.l)}</b></div>
    <div class="strong"><span>Итого без гранта — рассчитывайте на это</span><b>${usd(total0)}</b><small>≈ ${kzt(total0)} в год</small></div>
    <div class="cond"><span>Условный сценарий: грант до ${u.gr}% на обучение — не гарантирован</span><b>${usd(costG)}</b><small>≈ ${kzt(costG)} в год</small></div>
  </div>
  <div class="tags"><span>GPA от ${u.g.toFixed(1)} из 4.0 (≈ ${(u.g*1.25).toFixed(1)} из 5.0)</span><span>${u.e>0?`IELTS от ${u.e.toFixed(1)}`:"IELTS не требуется"}</span><span>${u.s>0?`SAT от ${u.s}`:"SAT не требуется"}</span></div>
  <details class="gr"><summary>Гранты и стипендии (${gl.length})</summary>${gl.map(x=>grantHTML(x,u)).join("")}
    <p class="hint">Размер и условия зависят от года набора, факультета и статуса абитуриента. Сверяй актуальный call на официальной странице. Процент «гранта до ${u.gr}%» в расчёте — условная оценка исходной базы, а не обещанная стипендия.</p></details>
  <div class="row">
    <button type="button" class="btn${sv?" on":""}" data-act="fav" data-i="${u.i}" aria-pressed="${sv}">${sv?"★ В избранном":"☆ В избранное"}</button>
    <button type="button" class="btn sec${cm?" on":""}" data-act="cmp" data-i="${u.i}" aria-pressed="${cm}">${cm?"В сравнении ✓":"Сравнить"}</button>
    <a class="btn sec" href="${esc(u.w)}" target="_blank" rel="noopener noreferrer">Официальный сайт ↗</a>
  </div></article>`;
}
function syncButtons(){
  $$('[data-act="fav"]').forEach(b=>{const on=S.saved.includes(U[+b.dataset.i].n);b.textContent=on?"★ В избранном":"☆ В избранное";b.setAttribute("aria-pressed",on);b.classList.toggle("on",on)});
  $$('[data-act="cmp"]').forEach(b=>{const on=S.cmp.includes(U[+b.dataset.i].n);b.textContent=on?"В сравнении ✓":"Сравнить";b.setAttribute("aria-pressed",on);b.classList.toggle("on",on)});
}
function toggleFav(i){
  const n=U[i].n,k=S.saved.indexOf(n);
  if(k>=0){S.saved.splice(k,1);toast("Удалено из избранного")}else{S.saved.push(n);toast("Добавлено в избранное")}
  save();onChange();
}
function toggleCmp(i){
  const n=U[i].n,k=S.cmp.indexOf(n);
  if(k>=0){S.cmp.splice(k,1);toast("Убрано из сравнения")}
  else if(S.cmp.length>=MAX_CMP){toast(`Можно сравнивать не более ${MAX_CMP} университетов`);return}
  else{S.cmp.push(n);toast("Добавлено в сравнение")}
  save();onChange();
}
function onChange(){syncButtons();renderHome();if(view==="fav")renderFav();if(view==="cmp")renderCmp();if(view==="plan")renderPlan();cmpBar()}
function cmpBar(){
  const n=S.cmp.length;$("#cmpbar").hidden=!(n>0&&view!=="cmp");
  $("#cmpn").textContent=`В сравнении: ${n} из ${MAX_CMP}`;
}

/* ---------- Навигация ---------- */
const VIEWS=["home","match","cat","fav","cmp","plan","calc"];
let view="home";
function show(v,push=true){
  if(!VIEWS.includes(v))v="home";
  if(push&&location.hash.slice(1)!==v){location.hash=v;return}
  view=v;
  $$("main>section").forEach(s=>s.hidden=s.id!==v);
  $$("nav button").forEach(b=>b.setAttribute("aria-current",String(b.dataset.go===v)));
  if(v==="home")renderHome();
  if(v==="match")showMatch();
  if(v==="cat")renderCat();
  if(v==="fav")renderFav();
  if(v==="cmp")renderCmp();
  if(v==="plan")renderPlan();
  if(v==="calc")calc();
  cmpBar();scrollTo(0,0);
}
window.addEventListener("hashchange",()=>show(location.hash.slice(1),false));

/* ---------- Главная ---------- */
const todayISO=()=>{const d=new Date(),p=n=>String(n).padStart(2,"0");return`${d.getFullYear()}-${p(d.getMonth()+1)}-${p(d.getDate())}`};
const fmtDate=s=>s.split("-").reverse().join(".");
function readiness(){
  const a=S.a,keys=[a.level,(a.all||a.countries.length)?"1":"",a.field,a.gpa,a.ielts,a.bval];
  if(a.level!=="Магистратура")keys.push(a.sat);
  return Math.round(keys.filter(v=>v!=="").length/keys.length*100);
}
function renderHome(){
  const res=S.done&&isComplete()?results():[],good=res.filter(r=>r.idx>=70);
  const save=good.reduce((m,r)=>Math.max(m,r.u.t*r.u.gr/100),0);
  const items=[[good.length,"подходящих программ (индекс соответствия ≥ 70)"],[save?usd(save):"—","условная экономия на обучении в год — не гарантирована"],[S.saved.length,"в избранном"],[readiness()+"%","готовность профиля"],[planPct()+"%","выполнено в плане"]];
  $("#stats").innerHTML=items.map(([v,l])=>`<div class="card stat"><b>${esc(v)}</b><span>${esc(l)}</span></div>`).join("");
  const dl=planTasks().filter(t=>S.plan.dl[t.id]).sort((a,b)=>S.plan.dl[a.id].localeCompare(S.plan.dl[b.id])),td=todayISO();
  $("#dl").innerHTML=dl.length?`<ul class="dl">${dl.map(t=>{const d=S.plan.dl[t.id],late=d<td&&!S.plan.done[t.id];return`<li><span>${esc(t.t)}${S.plan.done[t.id]?" ✓":""}</span><b>${esc(fmtDate(d))}${late?" · просрочено":""}</b></li>`}).join("")}</ul><p class="hint">Даты введены вами и не подтверждены университетами.</p>`
    :`<p class="hint">Здесь появятся ваши даты из раздела «Мой путь». Официальные дедлайны университетов зависят от программы и года на официальной странице выбранной программы.</p><div class="row"><button class="btn sec sm" data-go="plan">Открыть «Мой путь»</button></div>`;
}

/* ---------- Анкета ---------- */
let editing=!(S.done&&isComplete()),step=0;
const kzSel=()=>S.a.all||S.a.countries.includes("Казахстан");

/* мультивыбор стран */
function tagsHTML(){
  if(S.a.all)return`<button type="button" class="tag" data-act="rmc" data-c="*" aria-label="Убрать вариант «Все страны»">Все страны <span aria-hidden="true">×</span></button>`;
  if(!S.a.countries.length)return`<span class="hint">Ничего не выбрано</span>`;
  return S.a.countries.map(c=>`<button type="button" class="tag" data-act="rmc" data-c="${esc(c)}" aria-label="Убрать страну ${esc(c)}">${esc(c)} <span aria-hidden="true">×</span></button>`).join("");
}
function syncCountryUI(){
  const t=$("#cTags");if(!t)return;
  t.innerHTML=tagsHTML();
  $("#cAll").checked=S.a.all;
  $$("#cList input").forEach(i=>{i.checked=S.a.countries.includes(i.value)});
  $("#cHint").textContent=S.a.all?"Выбрано: все страны без ограничений.":`Выбрано стран: ${S.a.countries.length} из ${COUNTRIES.length}.`;
}
function drawCountryList(){
  const q=normStr($("#cSearch").value),l=COUNTRIES.filter(c=>!q||normStr(c).includes(q));
  $("#cList").innerHTML=l.length?l.map(c=>`<label class="opt"><input type="checkbox" value="${esc(c)}"><span>${esc(c)}</span><em>${U.filter(u=>u.c===c).length}</em></label>`).join(""):`<p class="hint" style="padding:14px">Страна не найдена.</p>`;
  syncCountryUI();
}
function afterCountryChange(){save();syncCountryUI();$("#rTags").innerHTML=tagsHTML();if(!editing)renderResults();renderHome()}

const STEPS=[
{key:"level",title:"Какой уровень обучения вас интересует?",
 render:()=>`<div class="field"><label for="f">Уровень</label><select id="f"><option value="">Выберите уровень</option><option>Бакалавриат</option><option>Магистратура</option></select></div>`,
 mount(){$("#f").value=S.a.level},
 collect(){const v=$("#f").value;if(!v)return"Выберите уровень обучения.";S.a.level=v;return""}},
{key:"countries",title:"В каких странах вы хотите учиться?",
 render:()=>`<fieldset class="field"><legend class="sr">Страны обучения</legend>
  <label class="opt all"><input type="checkbox" id="cAll"><span><b>Все страны</b> — без ограничений</span></label>
  <div class="cp-tools"><input id="cSearch" type="search" placeholder="Поиск страны…" aria-label="Поиск страны" autocomplete="off">
  <button type="button" class="btn sec sm" id="cSelAll">Выбрать все страны</button><button type="button" class="btn sec sm" id="cClear">Очистить выбор</button></div>
  <div class="tagbox" id="cTags" aria-live="polite"></div>
  <div class="cp-list" id="cList" role="group" aria-label="Список стран"></div>
  <p class="hint" id="cHint"></p></fieldset>`,
 mount(){
  drawCountryList();
  $("#cSearch").addEventListener("input",drawCountryList);
  $("#cSearch").addEventListener("keydown",e=>{if(e.key==="Enter")e.preventDefault()});
  $("#cAll").addEventListener("change",e=>{if(e.target.checked){S.a.all=true;S.a.countries=[]}else S.a.all=false;afterCountryChange()});
  $("#cList").addEventListener("change",e=>{
    const i=e.target;if(i.type!=="checkbox")return;
    S.a.all=false;
    if(i.checked){if(!S.a.countries.includes(i.value))S.a.countries.push(i.value)}else S.a.countries=S.a.countries.filter(c=>c!==i.value);
    afterCountryChange();
  });
  $("#cSelAll").addEventListener("click",()=>{S.a.all=false;S.a.countries=[...COUNTRIES];afterCountryChange()});
  $("#cClear").addEventListener("click",()=>{S.a.all=false;S.a.countries=[];afterCountryChange()});
 },
 collect(){if(!S.a.all&&!S.a.countries.length)return"Выберите хотя бы одну страну или вариант «Все страны».";return""}},
{key:"field",title:"Какое направление обучения вас интересует?",
 render:()=>`<div class="field"><label for="f">Направление</label><select id="f"><option value="">Выберите направление</option><option value="any">Любое направление</option>${Object.entries(F).map(([k,n])=>`<option value="${k}">${esc(n)}</option>`).join("")}</select><p class="hint">В подбор попадают только университеты, где есть выбранное направление.</p></div>`,
 mount(){$("#f").value=S.a.field},
 collect(){const v=$("#f").value;if(!v)return"Выберите направление или вариант «Любое направление».";S.a.field=v;return""}},
{key:"gpa",title:"Каков ваш средний балл (GPA)?",
 render:()=>`<div class="field"><label for="fs">Шкала оценок</label><select id="fs"><option value="4">0–4 (международная)</option><option value="5">0–5 (Казахстан, школьный аттестат)</option></select></div>
  <div class="field"><label for="f" id="fl">GPA по шкале от 0 до 4</label><input id="f" type="number" step="0.01" min="0" max="4" inputmode="decimal"><p class="hint" id="gh"></p></div>`,
 mount(){
  $("#fs").value=S.a.scale;$("#f").value=S.a.gpa;
  const ui=()=>{const m=$("#fs").value,v=$("#f").value;$("#f").max=m;$("#fl").textContent=`GPA по шкале от 0 до ${m}`;$("#f").placeholder=m==="5"?"Например, 4.5":"Например, 3.6";
   $("#gh").textContent=m==="5"?(v!==""&&+v>=0&&+v<=5?`≈ ${(v*0.8).toFixed(2)} по шкале 4.0. Это приблизительный пересчёт, а не официальный эквивалент: каждый университет оценивает аттестат по своим правилам.`:"Оценки по 5-балльной шкале пересчитываются в 4.0 приблизительно (×0,8). Это не официальный эквивалент."):"Международная 4-балльная шкала."};
  $("#fs").addEventListener("change",ui);$("#f").addEventListener("input",ui);ui();
 },
 collect(){const m=$("#fs").value==="5"?5:4,v=$("#f").value.trim();S.a.scale=String(m);
  if(v===""||!(+v>=0&&+v<=m))return`Введите число от 0 до ${m}.`;S.a.gpa=v;return""}},
{key:"sat",title:"Какой у вас балл SAT?",skip:()=>S.a.level==="Магистратура",
 render:()=>`<div class="field"><label for="f">Балл SAT</label><input id="f" type="number" step="10" min="400" max="1600" placeholder="Например, 1350" inputmode="numeric"><p class="hint">Шкала от 400 до 1600. Если экзамен ещё не сдан, оставьте поле пустым. Многие университеты не требуют SAT.</p></div>`,
 mount(){$("#f").value=S.a.sat},
 collect(){const v=$("#f").value.trim();if(v===""){S.a.sat="";return""}if(!(+v>=400&&+v<=1600))return"Введите число от 400 до 1600.";S.a.sat=v;return""}},
{key:"ielts",title:"Какой у вас балл IELTS?",
 render:()=>`<div class="field"><label for="f">Балл IELTS</label><input id="f" type="number" step="0.5" min="0" max="9" placeholder="Например, 6.5" inputmode="decimal"><p class="hint">Если экзамен ещё не сдан, оставьте поле пустым.</p></div>`,
 mount(){$("#f").value=S.a.ielts},
 collect(){const v=$("#f").value.trim();if(v===""){S.a.ielts="";return""}if(!(+v>=0&&+v<=9))return"Введите число от 0 до 9.";S.a.ielts=v;return""}},
{key:"ent",title:"Какой у вас балл ЕНТ?",skip:()=>!(kzSel()&&S.a.level==="Бакалавриат"),
 render:()=>`<div class="field"><label for="f">Балл ЕНТ (необязательно)</label><input id="f" type="number" step="1" min="0" max="140" placeholder="Например, 110" inputmode="numeric"><p class="hint">Нужен только для казахстанских вузов и государственного гранта. Максимум баллов и проходные баллы зависят от года и специальности — проверьте актуальные данные. Если не сдавали, оставьте пустым.</p></div>`,
 mount(){$("#f").value=S.a.ent},
 collect(){const v=$("#f").value.trim();if(v===""){S.a.ent="";return""}if(!(+v>=0&&+v<=140))return"Введите число от 0 до 140.";S.a.ent=v;return""}},
{key:"budget",title:"Какой бюджет на год вы готовы выделить?",
 render:()=>`<div class="field"><label for="bc">Валюта ввода</label><select id="bc"><option value="KZT">Тенге (₸)</option><option value="USD">Доллары ($)</option></select></div>
  <div class="field"><label for="f">Бюджет в год</label><input id="f" type="number" min="0" step="any" inputmode="decimal"><p class="hint" id="bh"></p></div>
  <div class="field"><label for="br">Курс, ₸ за 1 $</label><input id="br" type="number" min="1" step="any"><p class="hint">Курс вводится вручную и не обновляется автоматически — укажите актуальный. Учитываются обучение и проживание.</p></div>`,
 mount(){
  $("#bc").value=S.a.bcur;$("#f").value=S.a.bval;$("#br").value=S.rate;
  const ui=()=>{const c=$("#bc").value,v=+$("#f").value,r=+$("#br").value;$("#f").placeholder=c==="KZT"?"Например, 6000000":"Например, 12000";
   $("#bh").textContent=$("#f").value!==""&&v>=0&&r>0?(c==="KZT"?`≈ ${nf.format(Math.round(v/r))} $ в год`:`≈ ${nf.format(Math.round(v*r))} ₸ в год`):"Можно вводить в тенге или долларах."};
  ["bc","f","br"].forEach(id=>$("#"+id).addEventListener("input",ui));ui();
 },
 collect(){const c=$("#bc").value,v=$("#f").value.trim(),r=+$("#br").value;
  if(v===""||!(+v>=0))return"Укажите годовой бюджет — число не меньше 0.";
  if(!(r>0))return"Укажите курс — число больше 0.";
  S.a.bcur=c;S.a.bval=v;S.rate=r;return""}}
];
const skipped=i=>!!(STEPS[i].skip&&STEPS[i].skip());
const activeSteps=()=>STEPS.map((_,i)=>i).filter(i=>!skipped(i));
function drawStep(){
  const s=STEPS[step];
  $("#q").textContent=s.title;$("#qf").innerHTML=s.render()+'<p class="err" id="e" role="alert"></p>';s.mount();
  const act=activeSteps(),pos=act.indexOf(step);
  $("#pb").style.width=((pos+1)/act.length*100)+"%";
  $("#stepno").textContent=`Шаг ${pos+1} из ${act.length}`;
  $("#back").hidden=pos<=0;$("#next").textContent=pos===act.length-1?"Подобрать программы":"Далее";
  const f=$("#qf input:not([type=checkbox]),#qf select");if(f)f.focus({preventScroll:true});
}
function goStep(key){
  const i=STEPS.findIndex(s=>s.key===key);if(i<0||skipped(i))return;
  editing=true;step=i;showMatch();drawStep();
}
$("#back").onclick=()=>{const act=activeSteps(),pos=act.indexOf(step);if(pos>0){step=act[pos-1];drawStep()}};
$("#wiz").addEventListener("submit",e=>{
  e.preventDefault();
  const err=STEPS[step].collect();
  if(err){$("#e").textContent=err;return}
  save();
  const act=activeSteps(),pos=act.indexOf(step);
  if(pos<act.length-1){step=act[pos+1];drawStep()}else{S.done=true;editing=false;save();showMatch();renderHome();scrollTo(0,0)}
});
$("#redo").onclick=()=>{editing=true;step=0;showMatch();drawStep()};
function showMatch(){
  $("#wiz").hidden=!editing;$("#out").hidden=editing;
  if(editing){if(!$("#qf").innerHTML)drawStep()}else renderResults();
}

/* ---------- Результаты ---------- */
function fillFieldSelect(sel,first){
  sel.innerHTML=`<option value="">${first}</option>`+Object.entries(F).map(([k,n])=>`<option value="${k}">${esc(n)}</option>`).join("");
}
const SORTS={idx:(a,b)=>b.idx-a.idx||a.total0-b.total0,cost0:(a,b)=>a.total0-b.total0,costG:(a,b)=>a.costG-b.costG,gr:(a,b)=>b.u.gr-a.u.gr,name:(a,b)=>a.u.n.localeCompare(b.u.n)};
function kzTips(res){
  const a=S.a,t=[];
  if(a.scale==="5")t.push("Ваш GPA по шкале 5.0 пересчитан в 4.0 приблизительно (×0,8). Это не официальный эквивалент: университеты применяют свои правила конвертации.");
  t.push("Требования к документам (перевод, апостиль, нострификация, академическая справка) зависят от страны и университета — проверьте раздел для международных абитуриентов на официальном сайте.");
  if(res.some(r=>r.u.c==="Казахстан"))t.push("Для казахстанских вузов и государственного гранта используется ЕНТ"+(a.ent!==""?` (ваш балл: ${a.ent})`:"")+". проходные баллы меняются по группе программ и году конкурса; смотрите ежегодные данные МНВО РК.");
  t.push(a.level==="Магистратура"?"Для магистратуры за рубежом стоит изучить программу «Болашак» и Chevening (условия, список стран и дедлайны — на официальных сайтах).":"Для бакалавриата за рубежом смотрите государственные программы вроде GKS, MEXT, CSC и гранты самих университетов — условия для граждан Казахстана проверяйте на официальных сайтах.");
  t.push(`Расчёты в тенге используют ваш курс: ${nf.format(S.rate)} ₸ за 1 $. Он вводится вручную и не обновляется автоматически.`);
  return t;
}
function renderResults(){
  $("#rTags").innerHTML=tagsHTML();
  const list=$("#list"),sum=$("#rsum");
  if(!isComplete()){sum.textContent="";$("#kz").innerHTML="";list.innerHTML=`<div class="card empty">Анкета заполнена не полностью.<br><button class="btn" type="button" data-act="step" data-k="level">Заполнить анкету</button></div>`;return}
  if(!S.a.all&&!S.a.countries.length){sum.textContent="";$("#kz").innerHTML="";list.innerHTML=`<div class="card empty">Страны не выбраны. Выберите хотя бы одну страну или «Все страны».<br><button class="btn" type="button" data-act="step" data-k="countries">Выбрать страны</button></div>`;return}
  const all=results(),fc=$("#rfield").value,fcat=$("#rcat").value,fb=$("#rbud").value;
  let l=all.filter(r=>(!fc||r.u.f.includes(fc))&&(!fcat||r.cat===fcat)&&(!fb||(fb==="ok"?r.bs==="ok":r.bs!=="over")));
  l.sort(SORTS[$("#rsort").value]||SORTS.idx);
  const cn=k=>all.filter(r=>r.cat===k).length;
  sum.textContent=`Найдено программ: ${all.length}. Reach: ${cn("reach")} · Match: ${cn("match")} · Safety: ${cn("safety")}. Показано: ${l.length}.`;
  $("#kz").innerHTML=`<div class="card"><h2 style="font-size:16px">Рекомендации для абитуриентов из Казахстана</h2><ul class="bul" style="font-size:14px;color:var(--mute)">${kzTips(all).map(x=>`<li>${esc(x)}</li>`).join("")}</ul></div>`;
  list.innerHTML=l.length?l.map(r=>uniCard(r.u,r)).join(""):`<div class="card empty">Нет программ под выбранные фильтры. Измените фильтры, страны, направление или бюджет.<br><button class="btn" type="button" data-act="step" data-k="countries">Изменить страны</button></div>`;
}
["rsort","rcat","rbud","rfield"].forEach(id=>$("#"+id).addEventListener("change",renderResults));

/* ---------- Каталог ---------- */
function renderCat(){
  const q=normStr($("#qs").value),c=$("#qc").value,f=$("#qf2").value,mx=$("#qm").value===""?Infinity:+$("#qm").value,o=$("#qo").value;
  const P=S.done&&isComplete()?prof():null;
  let l=U.filter(u=>(!q||normStr(u.n).includes(q)||normStr(u.c).includes(q))&&(!c||u.c===c)&&(!f||u.f.includes(f))&&(u.t+u.l<=mx));
  const cmpf={name:(a,b)=>a.n.localeCompare(b.n),cost0:(a,b)=>(a.t+a.l)-(b.t+b.l),gr:(a,b)=>b.gr-a.gr,gpa:(a,b)=>a.g-b.g}[o];
  l.sort(cmpf);
  $("#qcount").textContent=`Показано университетов: ${l.length} из ${U.length}`;
  $("#catlist").innerHTML=l.length?l.map(u=>uniCard(u,P?evaluate(u,P):null)).join(""):`<div class="card empty">Ничего не найдено. Измените запрос или фильтры.</div>`;
}
(function initCat(){
  $("#qc").innerHTML=`<option value="">Все страны</option>`+COUNTRIES.map(c=>`<option>${esc(c)}</option>`).join("");
  fillFieldSelect($("#qf2"),"Любое направление");fillFieldSelect($("#rfield"),"Любое направление");
  ["qs","qm"].forEach(id=>$("#"+id).addEventListener("input",renderCat));
  ["qc","qf2","qo"].forEach(id=>$("#"+id).addEventListener("change",renderCat));
})();

/* ---------- Избранное и сравнение ---------- */
function renderFav(){
  const P=S.done&&isComplete()?prof():null,l=S.saved.map(n=>byName.get(n)).filter(Boolean);
  $("#favlist").innerHTML=l.length?l.map(u=>uniCard(u,P?evaluate(u,P):null)).join(""):`<div class="card empty" style="grid-column:1/-1">В избранном пока пусто. Добавляйте университеты из подбора или каталога.<br><button class="btn" data-go="cat">Открыть каталог</button></div>`;
}
function renderCmp(){
  const l=S.cmp.map(n=>byName.get(n)).filter(Boolean),out=$("#cmpout");
  $("#cmpclr").hidden=!l.length;
  if(!l.length){out.innerHTML=`<div class="card empty">Выберите университеты для сравнения кнопкой «Сравнить».<br><button class="btn" data-go="cat">Открыть каталог</button></div>`;return}
  const minT=Math.min(...l.map(u=>u.t+u.l)),minC=Math.min(...l.map(u=>u.t*(1-u.gr/100)+u.l));
  const row=(h,fn,best)=>`<tr><th scope="row">${h}</th>${l.map(u=>{const x=fn(u);return`<td${best&&best(u)?' class="best"':""}>${x}</td>`}).join("")}</tr>`;
  out.innerHTML=`<div class="tblw"><table><thead><tr><th scope="col"><span class="sr">Показатель</span></th>${l.map(u=>`<th scope="col">${esc(u.n)}<br><button type="button" class="btn sec sm" data-act="cmp" data-i="${u.i}" style="margin-top:6px">Убрать</button></th>`).join("")}</tr></thead><tbody>
  ${row("Страна",u=>esc(u.c))}
  ${row("Направления",u=>esc([...u.f].map(k=>F[k]).join(", ")))}
  ${row("Обучение в год",u=>`${usd(u.t)}<br><small>≈ ${kzt(u.t)}</small>`)}
  ${row("Проживание и расходы в год",u=>`${usd(u.l)}<br><small>≈ ${kzt(u.l)}</small>`)}
  ${row("Итого без гранта (в год)",u=>`${usd(u.t+u.l)}<br><small>≈ ${kzt(u.t+u.l)}</small>`,u=>u.t+u.l===minT)}
  ${row("Условный сценарий с грантом (в год, не гарантирован)",u=>`${usd(u.t*(1-u.gr/100)+u.l)}<br><small>грант до ${u.gr}% · ≈ ${kzt(u.t*(1-u.gr/100)+u.l)}</small>`,u=>u.t*(1-u.gr/100)+u.l===minC)}
  ${row("Гранты и стипендии",u=>esc(grantsFor(u).map(x=>x.n).join("; ")))}
  ${row("GPA (ориентир)",u=>`${u.g.toFixed(1)} из 4.0<br><small>≈ ${(u.g*1.25).toFixed(1)} из 5.0</small>`)}
  ${row("IELTS (ориентир)",u=>u.e>0?u.e.toFixed(1):"не требуется")}
  ${row("SAT (ориентир)",u=>u.s>0?String(u.s):"не требуется")}
  ${row("Официальный сайт",u=>`<a href="${esc(u.w)}" target="_blank" rel="noopener noreferrer">Открыть ↗</a>`)}
  </tbody></table></div><p class="hint" style="margin-top:10px">Зелёным выделена минимальная стоимость. Все показатели ориентировочные — уточняйте на сайте университета.</p>`;
}

/* ---------- Мой путь ---------- */
function targets(){
  if(S.saved.length)return S.saved.map(n=>byName.get(n)).filter(Boolean);
  if(S.done&&isComplete())return results().sort(SORTS.idx).slice(0,3).map(r=>r.u);
  return[];
}
function planTasks(){
  const T=targets(),P=prof(),bach=P.level==="Бакалавриат",names=T.map(u=>u.n).join(", ");
  let tests;
  if(!T.length)tests="Когда выберете университеты, здесь появятся их ориентировочные требования к IELTS и SAT.";
  else{
    const ie=T.map(u=>u.e).filter(x=>x>0),sa=T.map(u=>u.s).filter(x=>x>0),p=[];
    if(ie.length){const mx=Math.max(...ie);p.push(`IELTS: ориентиры от ${Math.min(...ie).toFixed(1)} до ${mx.toFixed(1)}.`+(P.ielts===null?" У вас пока нет результата.":P.ielts>=mx?" Ваш результат покрывает все выбранные вузы.":` Ваш результат ${P.ielts}: до максимума не хватает ${(mx-P.ielts).toFixed(1)}.`))}
    if(bach&&sa.length){const mx=Math.max(...sa);p.push(`SAT: ориентиры от ${Math.min(...sa)} до ${mx}.`+(P.sat===null?" У вас пока нет результата.":P.sat>=mx?" Ваш результат покрывает все выбранные вузы.":` Ваш результат ${P.sat}: до максимума не хватает ${mx-P.sat}.`))}
    tests=p.length?p.join(" "):"Для выбранных университетов IELTS/SAT не указаны как обязательные — проверьте на их сайтах.";
  }
  let fin="Ориентир стоимости появится, когда вы выберете университеты. Требования к подтверждению средств зависят от страны и университета.";
  if(T.length){const c=T.map(u=>u.t+u.l);fin=`Ориентировочная стоимость года без гранта: от ${usd(Math.min(...c))} до ${usd(Math.max(...c))} (≈ ${kzt(Math.min(...c))} – ${kzt(Math.max(...c))}). Состав и сумму подтверждающих документов по правилам страны и принимающего университета.`}
  const tasks=[
   {id:"req",t:"Проверить требования университета",d:T.length?`Сверьте требования на официальных сайтах: ${names}.`:"Выберите университеты в подборе или добавьте их в избранное — план станет персональным.",links:T.map(u=>[u.n,u.w])},
   {id:"tests",t:"Подготовить IELTS/SAT",d:tests}
  ];
  if(T.some(u=>u.c==="Казахстан")||(!T.length&&kzSel()&&bach))tasks.push({id:"ent",t:"ЕНТ и государственный грант (для вузов Казахстана)",d:"Проверьте даты и порядок ЕНТ и подачи на грант. проходные баллы меняются по группе программ и году конкурса; смотрите ежегодные данные МНВО РК."+(P.ent!==null?` Ваш балл ЕНТ: ${P.ent}.`:"")});
  tasks.push(
   {id:"doc",t:"Подготовить аттестат или диплом",d:"Уточните, нужны ли перевод, апостиль или нострификация: требования зависят от страны и университета."+(S.a.scale==="5"?" Вы указали оценки по шкале 5.0 — проверьте, как университет принимает такую шкалу.":"")},
   {id:"tr",t:"Подготовить академическую справку (транскрипт)",d:"Запросите в школе или вузе справку с оценками. Уточните требуемый язык и формат."},
   {id:"mot",t:"Написать мотивационное письмо",d:"Объясните выбор направления и университета. Лучше адаптировать письмо под каждую программу."},
   {id:"rec",t:"Получить рекомендательные письма",d:"Договоритесь с преподавателями заранее и выясните, сколько писем и в каком формате нужно."},
   {id:"fin",t:"Подготовить финансовые документы",d:fin},
   {id:"app",t:"Подать заявку",d:"Подавайте документы через официальный портал университета. Сроки подачи вносите сами после проверки на сайте."},
   {id:"res",t:"Отслеживать результат",d:"Следите за статусом заявки и письмами от университета, сохраняйте подтверждения."}
  );
  return tasks;
}
function planPct(){const t=planTasks();return t.length?Math.round(t.filter(x=>S.plan.done[x.id]).length/t.length*100):0}
function updatePlanProgress(){
  const t=planTasks(),n=t.filter(x=>S.plan.done[x.id]).length,p=t.length?Math.round(n/t.length*100):0;
  $("#plabel").textContent=`Выполнено: ${n} из ${t.length} (${p}%)`;$("#pfill").style.width=p+"%";$("#pbar2").setAttribute("aria-valuenow",p);
  $$("#tasks .task").forEach(li=>li.classList.toggle("done",!!S.plan.done[li.dataset.id]));
}
function renderPlan(){
  const t=planTasks(),T=targets();
  $("#ptargets").innerHTML=T.length?`План строится для: ${esc(T.map(u=>u.n).join(", "))}${S.saved.length?" (из избранного).":" (лучшие варианты подбора)."}`:`Пройдите подбор или добавьте университеты в избранное, чтобы план стал персональным.`;
  $("#tasks").innerHTML=t.map(x=>`<li class="task" data-id="${x.id}"><label class="chk"><input type="checkbox" data-task="${x.id}"${S.plan.done[x.id]?" checked":""}><span class="tt">${esc(x.t)}</span></label>
   <p>${esc(x.d)}</p>${x.links&&x.links.length?`<div class="links">${x.links.map(([n,u])=>`<a href="${esc(u)}" target="_blank" rel="noopener noreferrer">${esc(n)} ↗</a>`).join("")}</div>`:""}
   <div class="tdl"><label for="dl_${x.id}">Мой дедлайн (вводится вручную, не подтверждён)</label><input id="dl_${x.id}" type="date" data-dl="${x.id}" value="${esc(S.plan.dl[x.id]||"")}"></div></li>`).join("");
  updatePlanProgress();
}
$("#tasks").addEventListener("change",e=>{
  const t=e.target;
  if(t.dataset.task){if(t.checked)S.plan.done[t.dataset.task]=true;else delete S.plan.done[t.dataset.task];save();updatePlanProgress();renderHome()}
  else if(t.dataset.dl){const v=t.value;if(/^\d{4}-\d{2}-\d{2}$/.test(v))S.plan.dl[t.dataset.dl]=v;else delete S.plan.dl[t.dataset.dl];save();renderHome()}
});
$("#planreset").onclick=()=>{if(confirm("Сбросить отметки и даты в плане?")){S.plan={done:{},dl:{}};save();renderPlan();renderHome();toast("Прогресс сброшен")}};

/* ---------- Калькулятор ---------- */
const CF=["c1","c2","c3","c4","c5","c6"];
function mountCalc(){
  $("#cu").innerHTML=`<option value="">— не выбрано —</option>`+U.map(u=>`<option value="${u.i}">${esc(u.n)} (${esc(u.c)})</option>`).join("");
  $("#cc").value=S.calc.cur;CF.forEach((id,i)=>$("#"+id).value=S.calc.v[i]);$("#cg").value=S.calc.g;$("#cy").value=S.calc.y;$("#cr").value=S.rate;
}
function calc(){
  const cur=$("#cc").value,r=+$("#cr").value,v=CF.map(id=>$("#"+id).value===""?NaN:+$("#"+id).value),gp=+$("#cg").value,y=+$("#cy").value;
  const bad=v.some(x=>!isFinite(x)||x<0)||!isFinite(gp)||gp<0||gp>100||!Number.isInteger(y)||y<1||y>8||!(r>0)||$("#cg").value===""||$("#cy").value==="";
  $("#cerr").textContent=bad?"Проверьте значения: суммы не могут быть пустыми или отрицательными, грант — от 0 до 100%, срок — целое число от 1 до 8, курс — больше 0.":"";
  if(bad){$("#cres").innerHTML='<div class="empty">Введите корректные данные, чтобы увидеть расчёт.</div>';return}
  S.calc={cur,v,g:gp,y};save();
  const k=cur==="KZT"?1/r:1,tuition=v[0]*k,living=(v[1]+v[2]+v[3]+v[4]+v[5])*k;
  const sc=[["Без гранта",0],[`Частичный грант (${gp}%)`,gp],["Полный грант на обучение",100]].map(([n,p])=>{const yr=tuition*(1-p/100)+living;return{n,p,yr,mo:yr/12,tot:yr*y,save:tuition*p/100*y}});
  const T=(n)=>`${nf.format(Math.round(n))} $ · ${nf.format(Math.round(n*r))} ₸`;
  $("#cres").innerHTML=`<div class="scn">${sc.map((s,i)=>`<div class="sc${i===1?" hl":""}"><h4>${esc(s.n)}</h4><b class="big">${nf.format(Math.round(s.yr))} $</b><small>≈ ${nf.format(Math.round(s.yr*r))} ₸ в год</small>
   <ul class="dl"><li><span>В месяц</span><b>${nf.format(Math.round(s.mo))} $</b></li><li><span>За ${y} лет</span><b>${nf.format(Math.round(s.tot))} $</b></li><li><span>Всего в тенге</span><b>${nf.format(Math.round(s.tot*r))} ₸</b></li><li><span>Экономия за ${y} лет</span><b>${s.p?nf.format(Math.round(s.save))+" $":"—"}</b></li></ul></div>`).join("")}</div>
   <div class="bars" aria-label="Сравнение полной стоимости">${sc.map(s=>`<div><div class="l"><span>${esc(s.n)}</span><span>${T(s.tot)}</span></div><div class="t"><i style="width:${sc[0].tot>0?Math.max(2,s.tot/sc[0].tot*100):0}%"></i></div></div>`).join("")}</div>
   <p class="hint" style="margin-top:12px">Расчёт: (обучение − грант) + проживание, питание, транспорт, страхование и прочее. Полный грант покрывает только обучение — расходы на жизнь остаются на вас, если условия конкретного гранта не говорят иное. Сценарии с грантом условные и не гарантированы.</p>`;
}
$("#calc").addEventListener("input",e=>{
  if(e.target.id==="cu")return;
  if(e.target.id==="cr"){const r=+e.target.value;if(r>0)setRate(r,true)}
  calc();
});
$("#cc").addEventListener("change",()=>{
  const old=S.calc.cur,now=$("#cc").value;if(old===now)return;
  const f=now==="KZT"?S.rate:1/S.rate;
  CF.forEach(id=>{const x=+$("#"+id).value;if(isFinite(x))$("#"+id).value=now==="KZT"?Math.round(x*f):Math.round(x*f*100)/100});
  S.calc.cur=now;calc();
});
$("#cu").addEventListener("change",e=>{
  const u=U[+e.target.value];if(!u){$("#cnote").textContent="";return}
  const f=$("#cc").value==="KZT"?S.rate:1;
  $("#c1").value=Math.round(u.t*f);$("#c2").value=Math.round(u.l*f);["c3","c4","c5","c6"].forEach(id=>$("#"+id).value=0);
  $("#cg").value=u.gr;
  $("#cnote").textContent="Подставлены ориентировочные данные из базы: в «Проживание» включены основные расходы на жизнь. Процент гранта — условный ориентир, не подтверждён.";
  calc();
});
let rateT;
function setRate(r,fromCalc){
  S.rate=r;save();
  if(!fromCalc&&$("#cr"))$("#cr").value=r;
  clearTimeout(rateT);rateT=setTimeout(()=>{renderHome();if(view==="cat")renderCat();if(view==="fav")renderFav();if(view==="cmp")renderCmp();if(view==="match"&&!editing)renderResults();if(view==="plan")renderPlan()},200);
}

/* ---------- Общие обработчики ---------- */
document.addEventListener("click",e=>{
  const g=e.target.closest("[data-go]");
  if(g){show(g.dataset.go);return}
  const b=e.target.closest("[data-act]");if(!b)return;
  const a=b.dataset.act;
  if(a==="fav")toggleFav(+b.dataset.i);
  else if(a==="cmp"){toggleCmp(+b.dataset.i);if(view==="cmp")renderCmp()}
  else if(a==="cmpclear"){S.cmp=[];save();onChange();toast("Сравнение очищено")}
  else if(a==="city"){openCity(+b.dataset.i)}
  else if(a==="step")goStep(b.dataset.k);
  else if(a==="rmc"){
    const c=b.dataset.c;
    if(c==="*")S.a.all=false;else S.a.countries=S.a.countries.filter(x=>x!==c);
    afterCountryChange();
  }
});

/* ---------- Запуск ---------- */
mountCalc();
drawStep();
show(location.hash.slice(1)||"home",false);
